use charlotte_protocol_s3 as wire;
use zeroize::Zeroizing;
mod support;
use support::observe;
fn fixture() -> wire::Profile<'static> {
    wire::Profile {
        endpoint_ipv4: [192, 0, 2, 1],
        host: b"ZZZZZZZZ.local",
        port: 443,
        tls: true,
        ca_certificate_der: b"ZZZZZZZZ-public-ca",
        region: b"us-east-1",
        bucket: b"ZZZZZZZZ-bucket",
        prefix: b"ZZZZZZZZ/path",
        access_key: b"ZZZZZZZZ-access",
        secret_key: b"ZZZZZZZZ-public-secret",
        namespace: b"ZZZZZZZZ-namespace",
        rights: wire::RIGHT_GET | wire::RIGHT_PUT | wire::RIGHT_DELETE,
    }
}

fn secret_offset(profile: &wire::Profile<'_>) -> usize {
    wire::PROFILE_HEADER_LEN
        + profile.host.len()
        + profile.region.len()
        + profile.bucket.len()
        + profile.prefix.len()
        + profile.access_key.len()
}

#[test]
fn encoded_secret_release(){
 let observed=observe(0,0,secret_offset(&fixture()),||{let encoded=fixture().encode().unwrap();drop(encoded);});
 assert!(observed.copy_erased,"encoded secret retained: {observed:?}");
}
#[test]
fn abandoned_secret_release(){
 fn rejected()->Option<()>{let _encoded=fixture().encode()?;None}
 let observed=observe(0,0,secret_offset(&fixture()),||assert!(rejected().is_none()));
 assert!(observed.copy_erased,"abandoned secret retained: {observed:?}");
}
#[test]
fn existing_kernel_wrapper_erases(){
 let observed=observe(0,0,secret_offset(&fixture()),||{let encoded=Zeroizing::new(fixture().encode().unwrap());drop(encoded);});
 assert!(observed.copy_erased,"wrapped secret retained: {observed:?}");
 assert_eq!(observed.allocations,1);assert_eq!(observed.growths,0);assert_eq!(observed.copy_releases,1);
}
#[test]
fn debug_includes_credential_fields(){
 let profile=fixture();let text=format!("{profile:?}");
 assert!(text.contains(&format!("secret_key: {:?}",profile.secret_key)));
 assert!(text.contains(&format!("access_key: {:?}",profile.access_key)));
}

